if(TV=="")return h+(a>=6&&!S.mu&&!S.dr?["စာကြိုးစားလေ့လာ","ကျူရှင်တက် (-၂သိန်း)","အတန်းပြင်ပ လှုပ်ရှားမှု","ကျောင်းထွက်မည်"].concat(S.mf?["စာမေးပွဲ ပြန်ဖြေမည် (နောက်နှစ်)"]:[]).map(x=>`<button onclick='sch("${x}")'>${x}</button>`).join(""):S.uni?["စာကြိုးစားလေ့လာ","အလုပ်သင် (+၃သိန်း)","ကလပ်/လူမှုရေးလှုပ်ရှားမှု","စာမေးပွဲတွင် လာဘ်ပေး"].map((x,i)=>`<button onclick="un(${i})">${x}</button>`).join(""):"")+(S.job?`<button onclick="jw(0)">ကြိုးစားလုပ်ကိုင်</button><button onclick="jw(1)">အလုပ်ထွက်</button>`:"")+cvCard()+`<button class="pri" onclick="TV='edu';view(1)">🎓 ပညာရေး ›</button><button class="pri" onclick="TV='job';view(1)">💼 အလုပ်အကိုင် ›</button><button class="pri" onclick="TV='abr';view(1)">✈️ နိုင်ငံခြား ›</button>`;
